definitions.source:
defineBiome('dusk', {
  name: 'Сумеречный остров',
  short: 'тёплые сумерки',
  desc: 'Тёплые сумерки, травяные холмы, песчаные пляжи и кирпичный маяк.',
  blocks: {
    top: 'grass', soil: 'dirt', deep: 'stone', beach: 'sand', path: 'dirt', plaza: 'stone',
    wall: 'brick', pier: 'plank', post: 'bark', rock: 'stone', tower: 'brick', towerCap: 'brick', towerTop: 'stone', door: 'plank',
  },
  terrain: { height: 8.4, base: 0.42, hills: 0.8 },
  flora: [{ type: 'round_tree', count: 26, tries: 1200, spacing: 4.3, trunk: 'bark', crown: 'leaves' }],
  rocks: 6, ruins: 2, piers: 2,
  leafColors: ['#3a823d', '#5ea443', '#8fc64d'],
  palette: {},                 // per phase overrides: { dusk: {...}, twi: {...}, night: {...}, dawn: {...} }
  weather: null,               // { kind: 'snow' | 'rain' | 'ash' | 'spores', density, wind }
  ambience: { wind: 1, waves: 1 },
})

defineBiome('frost', {
  name: 'Ледяной фьорд',
  short: 'снег, лёд, сияние',
  desc: 'Снежные холмы, скользкий лёд у берега, ели и северное сияние над маяком.',
  lede: 'Собери монеты на ледяном фьорде, переживи метель и одолей Ледяного стража.',
  blocks: {
    top: 'snow', soil: 'frozen_dirt', deep: 'stone', beach: 'ice', path: 'packed_snow', plaza: 'frost_brick',
    wall: 'frost_brick', pier: 'plank', post: 'bark', rock: 'stone', tower: 'frost_brick', towerCap: 'frost_brick', towerTop: 'ice', door: 'plank',
  },
  terrain: { height: 9.4, base: 0.4, hills: 0.95 },
  flora: [{ type: 'pine', count: 24, tries: 1400, spacing: 4 }],
  rocks: 7, ruins: 2, piers: 2, shrines: 3,
  leafColors: ['#e3ebf7', '#c0cde6', '#2a6658'],       // what drifts down from the crowns: snow, mostly
  guardian: 'frost_warden',
  foes: { imp: 0 },                                     // frost imps take the imps' place
  weather: { kind: 'snow', density: 0.5, wind: [0.7, 0.25] },
  ambience: { wind: 1.8, waves: 0.6, gust: 0.35 },
  palette: {
    dusk: {
      skyTop: '#2a3f7a', skyHor: '#f0c2c9', fog: '#b9c3dd', fogD: 0.017, keyCol: '#ffd9c4', keyI: 2.4,
      hemiSky: '#e2eaff', hemiGnd: '#4a5272', hemiI: 1.7, deep: '#173a63', shallow: '#5ab7c9', foam: '#ffffff', wSky: '#d3dbf2',
      mist: 0.22, mistCol: '#e6ecf9', motes: 0.4, gain: [0.98, 1.0, 1.05], lift: [0.02, 0.02, 0.05],
    },
    twi: {
      skyTop: '#16224f', skyHor: '#9a83c4', fog: '#6f74a3', keyCol: '#c8b0ff', hemiSky: '#a9b4e8', hemiGnd: '#272a44',
      deep: '#11284f', shallow: '#2e7a9a', wSky: '#8d86c2', mistCol: '#a7a6d6', aurora: 0.35, auroraA: '#4dffb0', auroraB: '#8a6bff',
    },
    night: {
      skyTop: '#030a1c', skyHor: '#15305a', fog: '#132240', keyCol: '#a9c4ff', hemiSky: '#5b74b8', deep: '#08162e', shallow: '#18507a',
      wSky: '#2a4a7a', mistCol: '#5d77b0', aurora: 1, auroraA: '#3dffa8', auroraB: '#7a6bff', flies: 0.3,
    },
    dawn: { skyHor: '#ffe0c8', fog: '#e2d6dc', keyCol: '#fff0d8', aurora: 0 },
  },
})

defineBiome('sunken', {
  name: 'Затонувший город',
  short: 'подводный мир',
  desc: 'Серо-жёлтое дно из кубиков, затонувший собор, рыбы, батискаф и чудища глубин. Держи прыжок, чтобы всплыть к Острову сумерек.',
  lede: 'Собери жемчужины на дне, одолей хранителя глубин и зажги маяк. Всплыви — и увидишь берег Острова сумерек.',
  underwater: true,
  blocks: {
    top: 'sand', soil: 'stone', deep: 'stone', beach: 'sand', path: 'stone', plaza: 'stone',
    wall: 'stone', pier: 'plank', post: 'bark', rock: 'stone', tower: 'stone', towerCap: 'stone', towerTop: 'sand', door: 'plank',
  },
  terrain: { height: 8.4, base: 0.42, hills: 0.8, seabed: 6.2 },
  flora: [],
  rocks: 6, ruins: 2, piers: 0,
  guardian: 'uw_kraken',
  foes: { imp: 0, shade: 0, lantern_jelly: 0, rose_jelly: 0 },
  leafColors: ['#7fe0e8', '#4fb8c8', '#a8f0e0'],
  weather: null,
  ambience: { wind: 0.2, waves: 0.0 },
  onTerrain(g) {      // grey rock patches break up the yellow sand
    const { hgt, kind, vox, at, ci, W, D } = g;
    for (let z = 0; z < D; z++) for (let x = 0; x < W; x++) {
      const i = ci(x, z), h = hgt[i];
      if (h < 5 || kind[i] !== 0) continue;
      const n = Math.sin(x * 0.31 + 1.7) * Math.cos(z * 0.27 - 0.6) + Math.sin((x + z) * 0.13 + 2.2) * 0.8;
      if (n > 0.55) vox[at(x, h - 1, z)] = g.block('stone');
    }
  },
  palette: {
    dusk: {
      skyTop: '#06304d', skyHor: '#1f8fb0', fog: '#0b5c7c', fogD: 0.05, keyCol: '#ffe9b4', keyI: 2.4, sunEl: 0.5, sunVis: 0, moonMix: 0,
      hemiSky: '#bfe6ee', hemiGnd: '#16505e', hemiI: 1.55, mist: 0, mistCol: '#2a8aa8', motes: 1.4, flies: 0.35, stars: 0, wisp: 0.5,
      gain: [1.0, 1.08, 1.14], lift: [0.0, 0.05, 0.09], bloom: 0.62, grain: 0.04, vig: 0.4,
    },
    twi: {
      skyTop: '#052a45', skyHor: '#17789a', fog: '#094a68', fogD: 0.056, keyCol: '#8fdcf2', keyI: 1.7, sunEl: 0.5, sunVis: 0, moonMix: 0,
      hemiSky: '#9fd4e4', hemiGnd: '#103f4e', hemiI: 1.3, mist: 0, mistCol: '#2a8aa8', motes: 1.2, flies: 0.6, stars: 0, wisp: 1,
      gain: [0.98, 1.06, 1.14], lift: [0.0, 0.05, 0.1], bloom: 0.75, grain: 0.05, vig: 0.45,
    },
    night: {
      skyTop: '#031c30', skyHor: '#0e5a78', fog: '#06374f', fogD: 0.062, keyCol: '#7fc8e8', keyI: 1.3, sunEl: 0.5, sunVis: 0, moonMix: 0,
      hemiSky: '#7fb8d0', hemiGnd: '#0a2f3c', hemiI: 1.0, mist: 0, mistCol: '#2a8aa8', motes: 1.0, flies: 1, stars: 0, wisp: 1,
      gain: [0.96, 1.04, 1.14], lift: [0.0, 0.05, 0.11], bloom: 0.9, grain: 0.055, vig: 0.5,
    },
    dawn: {
      skyTop: '#0a4a6a', skyHor: '#3ab0c8', fog: '#12708e', fogD: 0.045, keyCol: '#d8fbff', keyI: 2.6, sunEl: 0.5, sunVis: 0, moonMix: 0,
      hemiSky: '#d0f0f4', hemiGnd: '#1c6272', hemiI: 1.8, mist: 0, mistCol: '#4aa8c0', motes: 1.4, flies: 0.2, stars: 0, wisp: 0.4,
      gain: [1.02, 1.08, 1.12], lift: [0.0, 0.05, 0.08], bloom: 0.55,
    },
  },
})
